-- Adaptive streaming assets generated by the media pipeline.
alter table public.videos add column if not exists hls_url text;
alter table public.videos add column if not exists dash_url text;
alter table public.videos add column if not exists video_url_low text;
alter table public.videos add column if not exists video_url_medium text;
alter table public.videos add column if not exists thumbnail_url_low text;
alter table public.videos add column if not exists thumbnail_url_medium text;

comment on column public.videos.hls_url is 'Master HLS playlist (.m3u8) with adaptive bitrate variants.';
comment on column public.videos.dash_url is 'Optional MPEG-DASH manifest (.mpd).';
comment on column public.videos.video_url_low is 'Fallback low bitrate MP4 for clients that cannot play HLS.';
comment on column public.videos.video_url_medium is 'Fallback medium bitrate MP4 for clients that cannot play HLS.';
